"""Estimator tests: hide a true build, feed observations generated by the
damage calculator itself, and check the posterior concentrates correctly."""

import pytest

from pokechamp.damage import calc_damage
from pokechamp.estimator import InconsistentObservation, StatEstimator, effective_speed
from pokechamp.schemas import PokemonSet, stat_table

MY_TUSK = PokemonSet(species="Great Tusk")
MY_CHOMP = PokemonSet(
    species="Garchomp", nature="Jolly", evs={**stat_table(), "atk": 252, "spe": 252}
)


def observed_percent(attacker, defender, move, roll_index=8):
    """Simulate one in-game damage event with a mid roll."""
    res = calc_damage(attacker, defender, move)
    return 100.0 * res.rolls[roll_index] / res.defender_hp


def test_damage_dealt_narrows_to_max_attack():
    hidden = PokemonSet(
        species="Garchomp", nature="Jolly",
        evs={**stat_table(), "atk": 252, "spe": 252, "hp": 4}, item="Choice Band",
    )
    est = StatEstimator("Garchomp", ruleset="gen9")
    pct = observed_percent(hidden, MY_TUSK, "Earthquake")
    est.observe_damage_dealt("Earthquake", MY_TUSK, pct, tolerance=0.5)

    # every surviving candidate must be a max-attack build with a power item
    assert est.marginal(lambda c: c.evs["atk"]).keys() == {252}
    assert set(est.marginal(lambda c: c.item)) <= {"Choice Band", "Life Orb"}
    assert est.stat_summary()["atk"]["min"] >= 182


def test_speed_observation_stacks_with_damage():
    hidden = PokemonSet(
        species="Garchomp", nature="Jolly",
        evs={**stat_table(), "atk": 252, "spe": 252, "hp": 4}, item="Choice Band",
    )
    est = StatEstimator("Garchomp", ruleset="gen9")
    pct = observed_percent(hidden, MY_TUSK, "Earthquake")
    est.observe_damage_dealt("Earthquake", MY_TUSK, pct, tolerance=0.5)
    est.observe_speed(opponent_moved_first=True, reference_speed=150)

    assert est.marginal(lambda c: c.evs["spe"]).keys() == {252}
    # the true build is among the survivors
    survivors = [c for c, _ in est.posterior()]
    assert any(
        c.nature == "Jolly" and c.item == "Choice Band" and c.evs["atk"] == 252
        for c in survivors
    )


def test_damage_taken_identifies_wall():
    hidden = PokemonSet(
        species="Garchomp", nature="Impish",
        evs={**stat_table(), "hp": 252, "def": 252, "spd": 4},
    )
    est = StatEstimator("Garchomp", ruleset="gen9")
    pct = observed_percent(MY_CHOMP, hidden, "Earthquake")
    est.observe_damage_taken(MY_CHOMP, "Earthquake", pct, tolerance=0.5)

    assert est.marginal(lambda c: c.evs["def"]).keys() == {252}
    assert est.marginal(lambda c: c.evs["hp"]).keys() == {252}


def test_scarf_inference_from_speed():
    est = StatEstimator("Garchomp", ruleset="gen9")
    # something outsped my 200-speed reference: only Scarf builds can
    est.observe_speed(opponent_moved_first=True, reference_speed=200)
    assert est.marginal(lambda c: c.item).keys() == {"Choice Scarf"}
    # every survivor actually clears the reference (incl. +Spe-nature bulky
    # Scarf builds, not just 252 Spe ones)
    for cand, _ in est.posterior():
        assert effective_speed(cand) > 200


def test_trick_room_reverses_speed():
    est = StatEstimator("Garchomp", ruleset="gen9")
    est.observe_speed(opponent_moved_first=True, reference_speed=130, trick_room=True)
    for cand, _ in est.posterior():
        assert cand.item != "Choice Scarf"
        assert effective_speed(cand) < 130


def test_multihit_observation_uses_total_distribution():
    hidden = PokemonSet(
        species="Garchomp", nature="Impish",
        evs={**stat_table(), "hp": 252, "def": 252, "spd": 4},
    )
    res = calc_damage(MY_TUSK, hidden, "Bonemerang")  # 2 hits
    assert res.hits == 2
    # observe a total that is achievable but not equal to 2x any single roll
    totals = list(res.total_distribution())
    odd_total = next(t for t in totals if t % 2 == 1)
    pct = 100.0 * odd_total / res.defender_hp

    est = StatEstimator("Garchomp", ruleset="gen9")
    est.observe_damage_taken(MY_TUSK, "Bonemerang", pct, tolerance=0.3)
    survivors = [c for c, _ in est.posterior()]
    assert any(c.nature == "Impish" and c.evs["def"] == 252 for c in survivors)


def test_inconsistent_observation_raises():
    est = StatEstimator("Garchomp", ruleset="gen9")
    with pytest.raises(InconsistentObservation):
        est.observe_damage_dealt("Earthquake", MY_TUSK, percent=1.0, tolerance=0.5)


def test_observation_log():
    est = StatEstimator("Garchomp", ruleset="gen9")
    est.observe_speed(opponent_moved_first=False, reference_speed=169)
    assert len(est.log) == 1
    assert est.log[0].survivors < len(est.candidates)
